import { describe, expect, it } from "vitest";
import { quote } from "./quote.js";

describe("MHPCO quote -- base premiums", () => {
  it("empty item list -- premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
  });
  it.todo("single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 45 G");
  it.todo("single rune -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
  it.todo("single moonstone -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
});

describe("MHPCO quote -- component blocks", () => {
  it.todo("2 runes -- base premium 50 G (no block)");
  it.todo("3 runes -- base premium 60 G (block applies)");
  it.todo("4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -- base premium 175 G (no block; block requires exactly 3)");
  it.todo("2 runes + 1 moonstone -- base premium 75 G (no block: different types are not alike)");
  it.todo("3 runes + 3 moonstones -- base premium 120 G (two separate blocks, one per type)");
});

describe("MHPCO quote -- item-specific modifiers", () => {
  it.todo("cursed sword adds 50 % of that item's base premium -- 50 G surcharge");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge -- 30 G");
  it.todo("sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 -- both surcharges apply (50 G + 30 G)");
  it.todo("cursed sword + plain amulet -- policy base 160 G, curse adds 50 G (50 % of the cursed item only) = 210 G before policy modifiers and fee");
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years -- 20 % loyalty discount on the policy base premium");
  it.todo("customer with 1 year -- no loyalty discount");
  it.todo("first quote of the scenario -- 10 % first insurance surcharge on the policy base premium");
  it.todo("second quote of the scenario -- 15 % follow-up contract discount applies");
  it.todo("first insurance surcharge still applies to the second quote (each quoted item is a first insurance)");
  it.todo("5 G processing fee is added at the very end, after all percentage modifiers");
});

describe("MHPCO quote -- rounding", () => {
  it.todo("premium of 197.5 G rounds up to 198 G (in the MHPCO's favor)");
  it.todo("intermediate amounts stay fractional; only the final premium is rounded");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer, second quote, cursed steel sword enchantment 7 -- premium 160 G");
});

describe("MHPCO quote -- rejections", () => {
  it.todo("quote with an unknown item type (broomstick) throws an Error (adopted reading: unknown type is rejected; spec defines only non-zero CLI exit and stderr description)");
});

describe("MHPCO claim -- standard reimbursement", () => {
  it.todo("regular steel sword enchantment 3, damage 500 G -- payout 400 G (full minus 100 G deductible)");
  it.todo("rune (no enchantment, no material), damage 200 G -- payout 100 G (full minus 100 G deductible)");
  it.todo("damage below the deductible -- payout 0 G, never negative");
});
